    path = Path(candidate)
    try:
        if not path.is_file() or path.is_symlink():
            return None
        resolved = path.resolve(strict=True)
        root = allowed_root.resolve(strict=True)
    except OSError:
        return None
    if not _under_root(resolved, root) or resolved == root:
        return None
    return resolved


