        push = git.push(runner, "origin", branch, cwd=cwd)
        pushed = push.returncode == 0
    sha = git.try_rev_parse(runner, "HEAD", cwd=cwd) if pushed else head
    pending = (did_rebase or ci_fix_rebase_pending) and not pushed
